using namespace P4MapKit;using namespace P4MapKit::Material;namespace C=P4MapKit::CustomMaterial;
int checks=0;void Check(bool ok,const char* text){++checks;if(!ok)throw std::runtime_error(text);}template<class F>void Refuses(F f,const char* category){++checks;try{f();}catch(const Refused& e){if(e.name==category)return;throw;}throw std::runtime_error("expected shared sampler refusal");}
int main(){try{FMaterialUniformSet uniforms;FMaterialUniformTexture tex;uniforms.Textures.push_back(tex);tex.TextureType=1;uniforms.Textures.push_back(tex);uniforms.ExternalTextureCount=1;C::ShaderBindings header;header.samplers=C::BuildResourceTable({{1,{{1,0},{3,1},{6,9},{7,4}}}},2);const auto contract=PrepareMaterialSharedSamplerContract(uniforms,header,1);Check(contract.Words==std::map<int,std::string>{{1424,"SSM_Wrap_WorldGroupSettings"},{1384,"SSM_Clamp_WorldGroupSettings"}},"external pairs included before exact shared tail");Check(!contract.VirtualLayoutUnclassified,"ordinary source layout classified");BindingContext binding;ApplyMaterialSharedSamplerContract(binding,contract);SymbolicArena arena;Binder binder(arena,binding);Check(binder.sampler_source("Albedo",1424,nullptr)=="/SSM_Wrap_WorldGroupSettings"&&binder.sampler_source("Albedo",1384,nullptr)=="/SSM_Clamp_WorldGroupSettings","shared material handles become exact graph sampler sources");const auto absent=PrepareMaterialSharedSamplerContract(uniforms,header,-1);Check(absent.Words.empty(),"no Material buffer creates no shared handles");auto virtualLayout=uniforms;virtualLayout.VirtualStackCount=1;auto virtualContract=PrepareMaterialSharedSamplerContract(virtualLayout,header,1);Check(virtualContract.VirtualLayoutUnclassified&&virtualContract.Words.empty(),"VT prefixes remain unclassified");auto virtualTexture=uniforms;virtualTexture.Textures[0].TextureType=4;Check(PrepareMaterialSharedSamplerContract(virtualTexture,header,1).VirtualLayoutUnclassified,"virtual category preserves named missing layout");auto unknown=uniforms;unknown.Textures[0].TextureType=5;Refuses([&]{PrepareMaterialSharedSamplerContract(unknown,header,1);},"material shared sampler layout");auto beyond=header;beyond.samplers=C::BuildResourceTable({{1,{{8,9}}}},2);Refuses([&]{PrepareMaterialSharedSamplerContract(uniforms,beyond,1);},"material shared sampler layout");auto conflict=header;conflict.samplers=C::BuildResourceTable({{1,{{6,9},{7,9}}}},2);Refuses([&]{PrepareMaterialSharedSamplerContract(uniforms,conflict,1);},"material shared sampler identity");auto corrupt=header;corrupt.samplers={999};Refuses([&]{PrepareMaterialSharedSamplerContract(uniforms,corrupt,1);},"material shared sampler table");binding.MaterialSharedSamplers[1424]="SSM_Clamp_WorldGroupSettings";Refuses([&]{ApplyMaterialSharedSamplerContract(binding,contract);},"material shared sampler identity");MaterialPreparedProgram prepared;prepared.BaseBinding.Uniforms=uniforms;prepared.BaseBinding.Buffers={{1,"Material"}};prepared.Header=header;Check(PrepareOriginalMaterialSharedSamplers(prepared).Words==contract.Words,"original structural packet supplies sampler contract");prepared.BaseBinding.Buffers[2]="Material";Refuses([&]{PrepareOriginalMaterialSharedSamplers(prepared);},"material shared sampler identity");std::cout<<"native shared sampler checks="<<checks<<"\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
